package main

// Regression tests for the round-2 P0 report. Fixtures live in
// testdata/regressions and are regenerated by generate.py there.

import (
	"bytes"
	"context"
	"fmt"
	"image"
	"image/color"
	"image/png"
	"os"
	"path/filepath"
	"testing"

	"github.com/gen2brain/webp"
)

const regressionDir = "testdata/regressions"

func regressionPath(name string) string { return filepath.Join(regressionDir, name) }

/* ------------------------------------------------------------------ */
/* P0-A: APNG and extension-blind animation dispatch                   */
/* ------------------------------------------------------------------ */

func TestP0AAPNGIsAddedAsAnimation(t *testing.T) {
	path := regressionPath("apng-6frames.png")
	frames, err := animationFrameCount(path)
	if err != nil {
		t.Fatal(err)
	}
	if frames != 6 {
		t.Fatalf("animationFrameCount = %d, want 6", frames)
	}
	if animated, err := isAnimatedFile(path); err != nil || !animated {
		t.Fatalf("isAnimatedFile = %v, %v; want true", animated, err)
	}

	service := newTestService(t)
	result, err := service.AddPaths([]string{path})
	if err != nil {
		t.Fatal(err)
	}
	if result.Added != 1 || len(result.Skipped) != 0 {
		t.Fatalf("added=%d skipped=%v", result.Added, result.Skipped)
	}
	item := result.Snapshot.Items[0]
	if !item.Animated {
		t.Fatal("APNG lost its animated flag; the still path would keep only frame one")
	}
	if item.Format != "PNG" {
		t.Fatalf("format = %q, want PNG", item.Format)
	}
}

func TestP0AAPNGIsKeptWhole(t *testing.T) {
	path := regressionPath("apng-6frames.png")
	source, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}

	service := &AnyPic{tempDir: t.TempDir()}
	result, err := service.compressOne(context.Background(), 1, path, "PNG", "apng-6frames.png", true, Settings{
		Format: "png", Quality: 82, Suffix: "-anypic",
	})
	if err != nil {
		t.Fatal(err)
	}
	if !result.passedThrough || result.keptOriginalReason != "animated_png" {
		t.Fatalf("passthrough=%v reason=%q, want true/animated_png", result.passedThrough, result.keptOriginalReason)
	}
	if result.path != path {
		t.Fatalf("result path = %q, want the original %q", result.path, path)
	}
	out, err := os.ReadFile(result.path)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(out, source) {
		t.Fatal("APNG bytes changed: the animation must be kept untouched")
	}
	if !bytes.Contains(out, []byte("acTL")) {
		t.Fatal("output lost acTL: the animation control chunk is gone")
	}
	if frames, err := animationFrameCount(result.path); err != nil || frames != 6 {
		t.Fatalf("output frames = %d, %v; want 6", frames, err)
	}
}

func TestP0ARenamedGIFStaysAnimated(t *testing.T) {
	path := regressionPath("renamed-gif.png")
	if frames, err := animationFrameCount(path); err != nil || frames != 5 {
		t.Fatalf("content sniff frames = %d, %v; want 5 (extension says PNG)", frames, err)
	}

	service := newTestService(t)
	added, err := service.AddPaths([]string{path})
	if err != nil {
		t.Fatal(err)
	}
	item := added.Snapshot.Items[0]
	if !item.Animated {
		t.Fatal("a GIF renamed .png was not detected as animated")
	}
	if item.Format != "GIF" {
		t.Fatalf("format = %q, want the sniffed GIF", item.Format)
	}

	result, err := service.compressOne(context.Background(), item.ID, path, item.Format, item.Name, item.Animated, Settings{
		Format: "auto", Quality: 82, Suffix: "-anypic",
	})
	if err != nil {
		t.Fatal(err)
	}
	if result.passedThrough {
		t.Fatalf("expected an animated WebP conversion, got passthrough (%q)", result.keptOriginalReason)
	}
	if result.format != "WEBP" || result.outputName != "renamed-gif-anypic.webp" {
		t.Fatalf("format=%q name=%q, want WEBP/renamed-gif-anypic.webp", result.format, result.outputName)
	}
	f, err := os.Open(result.path)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	anim, err := webp.DecodeAll(f)
	if err != nil {
		t.Fatal(err)
	}
	if len(anim.Image) != 5 {
		t.Fatalf("converted frames = %d, want 5", len(anim.Image))
	}
}

/* ------------------------------------------------------------------ */
/* P0-B: ICC colour space must match the output pixels                 */
/* ------------------------------------------------------------------ */

func TestP0BCMYKJPEGKeepsOriginal(t *testing.T) {
	path := regressionPath("cmyk-icc.jpg")
	source, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}

	service := &AnyPic{tempDir: t.TempDir()}
	result, err := service.compressOne(context.Background(), 1, path, "JPEG", "cmyk-icc.jpg", false, Settings{
		Format: "jpeg", Quality: 50, Suffix: "-anypic",
	})
	if err != nil {
		t.Fatal(err)
	}
	if !result.passedThrough || result.keptOriginalReason != "color_space" {
		t.Fatalf("passthrough=%v reason=%q, want true/color_space", result.passedThrough, result.keptOriginalReason)
	}
	if result.path != path {
		t.Fatalf("result path = %q, want the original %q", result.path, path)
	}
	out, err := os.ReadFile(result.path)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(out, source) {
		t.Fatal("CMYK JPEG was rewritten; its pixels or profile must not be touched")
	}
	if !bytes.Contains(out, []byte("ICC_PROFILE\x00")) {
		t.Fatal("the original CMYK profile disappeared")
	}
}

func TestP0BGrayJPEGWithRGBProfileDropsICC(t *testing.T) {
	path := regressionPath("gray-rgb-icc.jpg")

	service := &AnyPic{tempDir: t.TempDir()}
	result, err := service.compressOne(context.Background(), 2, path, "JPEG", "gray-rgb-icc.jpg", false, Settings{
		Format: "jpeg", Quality: 10, Suffix: "-anypic",
	})
	if err != nil {
		t.Fatal(err)
	}
	if result.passedThrough {
		t.Fatalf("q10 re-encode should beat the fixture; got passthrough (%q)", result.keptOriginalReason)
	}
	m := result.metadata
	if m == nil {
		t.Fatal("the source carried an ICC profile; the drop must be reported")
	}
	if m.ICCKept || !m.ICCDroppedIncompatible || m.ICCColorSpace != "RGB" {
		t.Fatalf("metadata = %+v, want incompatible RGB ICC dropped", m)
	}
	if !m.Dropped {
		t.Fatalf("metadata = %+v, Dropped must be true", m)
	}

	data, err := os.ReadFile(result.path)
	if err != nil {
		t.Fatal(err)
	}
	if bytes.Contains(data, []byte("ICC_PROFILE\x00")) {
		t.Fatal("output carries an RGB ICC profile on a grayscale JPEG")
	}
	decoded, _, err := image.Decode(bytes.NewReader(data))
	if err != nil {
		t.Fatal(err)
	}
	if _, ok := decoded.(*image.Gray); !ok {
		t.Fatalf("output pixels are %T, want *image.Gray", decoded)
	}
}

func TestP0BGrayPNGWithRGBProfileDropsICC(t *testing.T) {
	dir := t.TempDir()
	src := filepath.Join(dir, "gray.png")
	gray := image.NewGray(image.Rect(0, 0, 64, 48))
	for y := 0; y < 48; y++ {
		for x := 0; x < 64; x++ {
			gray.SetGray(x, y, color.Gray{Y: uint8(x*4 + y)})
		}
	}
	var buf bytes.Buffer
	enc := png.Encoder{CompressionLevel: png.BestSpeed} // leaves room for a smaller re-encode
	if err := enc.Encode(&buf, gray); err != nil {
		t.Fatal(err)
	}
	profile := make([]byte, 256)
	copy(profile[16:20], "RGB ")
	sourceChunk := makeICCPChunk(t, profile)
	// iCCP goes directly after IHDR (the first 33 bytes), like metadata.apply.
	data := append([]byte(nil), buf.Bytes()[:33]...)
	data = append(data, sourceChunk...)
	data = append(data, buf.Bytes()[33:]...)
	if err := os.WriteFile(src, data, 0o644); err != nil {
		t.Fatal(err)
	}

	service := &AnyPic{tempDir: t.TempDir()}
	result, err := service.compressOne(context.Background(), 3, src, "PNG", "gray.png", false, Settings{
		Format: "png", Quality: 82, Suffix: "-anypic",
	})
	if err != nil {
		t.Fatal(err)
	}
	if result.passedThrough {
		t.Fatalf("BestSpeed source should be beaten by a BestCompression re-encode (reason %q)", result.keptOriginalReason)
	}
	if result.metadata == nil || result.metadata.ICCKept || !result.metadata.ICCDroppedIncompatible {
		t.Fatalf("metadata = %+v, want RGB profile dropped as incompatible", result.metadata)
	}
	out, err := os.ReadFile(result.path)
	if err != nil {
		t.Fatal(err)
	}
	if bytes.Contains(out, []byte("iCCP")) {
		t.Fatal("output PNG carries an RGB iCCP on grayscale pixels")
	}
}

/* ------------------------------------------------------------------ */
/* P0-C: large PNGs decide by content and report fast mode             */
/* ------------------------------------------------------------------ */

func largePNGFixture(t *testing.T, fill func(x, y int) color.NRGBA, level png.CompressionLevel) (string, image.Image) {
	t.Helper()
	// Just above the 16M-pixel budget (16,785,409 pixels).
	const side = 4097
	img := image.NewNRGBA(image.Rect(0, 0, side, side))
	for y := 0; y < side; y++ {
		for x := 0; x < side; x++ {
			img.SetNRGBA(x, y, fill(x, y))
		}
	}
	path := filepath.Join(t.TempDir(), "large.png")
	f, err := os.Create(path)
	if err != nil {
		t.Fatal(err)
	}
	enc := png.Encoder{CompressionLevel: level}
	if err := enc.Encode(f, img); err != nil {
		f.Close()
		t.Fatal(err)
	}
	if err := f.Close(); err != nil {
		t.Fatal(err)
	}
	return path, img
}

func TestP0CLargePNGCompressibleContentGetsBestSearch(t *testing.T) {
	ui := func(x, y int) color.NRGBA {
		switch {
		case y%64 == 0:
			return color.NRGBA{R: 220, G: 224, B: 232, A: 255}
		case x > 80 && x < 2400 && y > 120 && y < 900:
			return color.NRGBA{R: 255, G: 255, B: 255, A: 255}
		case x > 3000 && x < 3012:
			return color.NRGBA{R: 120, G: 130, B: 150, A: 255}
		}
		return color.NRGBA{R: 245, G: 246, B: 248, A: 255}
	}
	path, img := largePNGFixture(t, ui, png.DefaultCompression)
	baseline, err := encodePNGStdlib(img, png.DefaultCompression)
	if err != nil {
		t.Fatal(err)
	}

	service := &AnyPic{tempDir: t.TempDir()}
	result, err := service.compressOne(context.Background(), 1, path, "PNG", "large.png", false, Settings{
		Format: "png", Quality: 82, Suffix: "-anypic",
	})
	if err != nil {
		t.Fatal(err)
	}
	if result.passedThrough {
		t.Fatalf("search result was not smaller than the source? reason=%q", result.keptOriginalReason)
	}
	if result.largeFastMode {
		t.Fatal("a compressible 6K-class PNG was labelled fast mode instead of searched")
	}
	if result.size >= int64(len(baseline))/2 {
		t.Fatalf("result %d bytes, baseline %d: the large-image search did not run", result.size, len(baseline))
	}
}

func TestP0CLargePNGDenseContentReportsFastMode(t *testing.T) {
	dense := func(x, y int) color.NRGBA {
		// Deterministic, high-entropy pixels; this compresses like a photo.
		v := uint32(x)*1664525 + uint32(y)*1013904223
		v ^= v >> 13
		return color.NRGBA{R: uint8(v), G: uint8(v >> 8), B: uint8(v >> 16), A: 255}
	}
	path, _ := largePNGFixture(t, dense, png.NoCompression)

	service := &AnyPic{tempDir: t.TempDir()}
	result, err := service.compressOne(context.Background(), 1, path, "PNG", "large.png", false, Settings{
		Format: "png", Quality: 82, Suffix: "-anypic",
	})
	if err != nil {
		t.Fatal(err)
	}
	if result.passedThrough {
		t.Fatalf("source was written uncompressed; the fast baseline should still beat it (reason %q)", result.keptOriginalReason)
	}
	if !result.largeFastMode {
		t.Fatal("large dense PNG silently used the fast path")
	}
}

/* ------------------------------------------------------------------ */
/* P0-D / P0-E: adds report overflow and unsupported folder formats    */
/* ------------------------------------------------------------------ */

func writeTinyPNGs(t *testing.T, dir string, n int) {
	t.Helper()
	var buf bytes.Buffer
	if err := png.Encode(&buf, image.NewNRGBA(image.Rect(0, 0, 1, 1))); err != nil {
		t.Fatal(err)
	}
	for i := 0; i < n; i++ {
		name := filepath.Join(dir, fmt.Sprintf("img%04d.png", i))
		if err := os.WriteFile(name, buf.Bytes(), 0o644); err != nil {
			t.Fatal(err)
		}
	}
}

func TestP0DOver500ImagesReportOverflow(t *testing.T) {
	dir := t.TempDir()
	writeTinyPNGs(t, dir, maxBatchSize+20)

	paths, skipped, overflow := collectImages([]string{dir})
	if len(paths) != maxBatchSize {
		t.Fatalf("collected %d paths, want %d", len(paths), maxBatchSize)
	}
	if overflow != 20 {
		t.Fatalf("overflow = %d, want 20", overflow)
	}
	if len(skipped) != 0 {
		t.Fatalf("unexpected per-file skips: %v", skipped)
	}

	service := newTestService(t)
	result, err := service.AddPaths([]string{dir})
	if err != nil {
		t.Fatal(err)
	}
	if result.Added != maxBatchSize || result.Overflow != 20 {
		t.Fatalf("added=%d overflow=%d, want %d/20", result.Added, result.Overflow, maxBatchSize)
	}
	if len(result.Skipped) != 0 {
		t.Fatalf("per-file skips = %v, want one aggregate overflow count", result.Skipped)
	}
	waitFor(t, "all thumbnails", func() bool {
		for _, item := range service.State().Items {
			if item.Thumb == "" {
				return false
			}
		}
		return true
	})
}

func TestP0EFolderReportsUnsupportedImageFormats(t *testing.T) {
	dir := t.TempDir()
	writeTinyPNGs(t, dir, 3)
	for _, name := range []string{"a.heic", "b.heic", "c.heic", "d.psd"} {
		if err := os.WriteFile(filepath.Join(dir, name), []byte("not decodable"), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	// Noise that must stay silent.
	for _, name := range []string{".DS_Store", "notes.txt", "clip.mov"} {
		if err := os.WriteFile(filepath.Join(dir, name), []byte("no"), 0o644); err != nil {
			t.Fatal(err)
		}
	}

	service := newTestService(t)
	result, err := service.AddPaths([]string{dir})
	if err != nil {
		t.Fatal(err)
	}
	if result.Added != 3 {
		t.Fatalf("added = %d, want 3", result.Added)
	}
	if len(result.Skipped) != 4 {
		t.Fatalf("skipped = %v, want four unsupported image files", result.Skipped)
	}
	for _, skip := range result.Skipped {
		if skip.Reason != tr().GoSkippedUnsupportedShort() {
			t.Fatalf("%s: reason = %q, want %q", skip.Name, skip.Reason, tr().GoSkippedUnsupportedShort())
		}
		if skip.Name == ".DS_Store" || skip.Name == "notes.txt" || skip.Name == "clip.mov" {
			t.Fatalf("non-image %q was reported as an unsupported image", skip.Name)
		}
	}
}

/* ------------------------------------------------------------------ */
/* P0-F: WebP ICC loss is reported                                     */
/* ------------------------------------------------------------------ */

func TestP0FWebPICCDropIsReported(t *testing.T) {
	path := regressionPath("webp-icc.webp")

	service := &AnyPic{tempDir: t.TempDir()}
	result, err := service.compressOne(context.Background(), 1, path, "WEBP", "webp-icc.webp", false, Settings{
		Format: "webp", Quality: 10, Suffix: "-anypic",
	})
	if err != nil {
		t.Fatal(err)
	}
	if result.passedThrough {
		t.Fatalf("q10 re-encode should beat the fixture; got passthrough (%q)", result.keptOriginalReason)
	}
	m := result.metadata
	if m == nil {
		t.Fatal("the source carried an ICCP chunk; the drop must be reported")
	}
	if m.ICCKept || !m.ICCDroppedUnsupported || !m.Dropped {
		t.Fatalf("metadata = %+v, want unsupported ICC drop reported", m)
	}
	data, err := os.ReadFile(result.path)
	if err != nil {
		t.Fatal(err)
	}
	if bytes.Contains(data, []byte("ICCP")) {
		t.Fatal("output unexpectedly carries an ICCP chunk")
	}
}
